window.AUTH=window.AUTH||{};window.AUTH["93-1783"]={"d":"93-1783","id":"1994/93-1783","n":"Director, Office of Workers' Compensation Programs v. Newport News Shipbuilding & Drydock Company","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the petitioner","date":"","url":"https://www.justice.gov/osg/media/219666/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/director-office-workers-compensation-programs-united-states-department-labor-petitioner--0","n":52}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep514/usrep514122/usrep514122.pdf","tr":false,"items":[{"t":"case","label":"Carozza v. United States Steel Corp.","cite":"727 F.2d 14","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/727/14/","by":{"0":"10"}},{"t":"case","label":"Director, OWCP v. Cargill, Inc.","cite":"718 F.2d 886","y":1983,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/718/886/","by":{"0":"17"}},{"t":"case","label":"Director, OWCP v. Eastern Coal Corp.","cite":"561 F.2d 632","y":1977,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/561/632/","by":{"0":"10"}},{"t":"case","label":"Director, OWCP v. National Van Lines, Inc.","cite":"613 F.2d 972","y":1979,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/613/972/","by":{"0":"17"}},{"t":"case","label":"Director, OWCP v. Newport News Shipbuilding & Dry Dock Co.","cite":"676 F.2d 110","y":1982,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/676/110/","by":{"0":"17"}},{"t":"case","label":"Far East Conference v. United States","cite":"342 U.S. 570","y":1952,"id":"scdb/1951-055","sc":1,"sum":"The United States brought this suit in the District Court to enjoin alleged violations of the Sherman Antitrust Act. The defendants were the Far East Conference, a voluntary association, and its constituent members, steanship companies engaged in \"outbound Far East trade.\" The agreement under which the Conference operated was approved by the predecessor of the Federal Maritime Boar d, exercising authority under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Gibas v. Saginaw Mining Co.","cite":"748 F.2d 1112","y":1984,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/748/1112/","by":{"0":"10"}},{"t":"case","label":"McCord v. Benefits Review Bd.","cite":"514 F.2d 198","y":1975,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/514/198/","by":{"0":"7"}},{"t":"case","label":"Nacirema Operating Co. v. Benefits Review Bd.","cite":"538 F.2d 73","y":1976,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/538/73/","by":{"0":"7"}},{"t":"case","label":"Nathanson v. NLRB","cite":"344 U.S. 25","y":1952,"id":"scdb/1952-006","sc":1,"sum":"1.. The Board is a \"creditor\" as respects the\" back-pay awards, within the meaning of the Bankruptcy Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Resources Defense Council, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["criminal-jury-venue","Criminal Jury and Venue Clause"],["treason","Treason Clause"],["treason-punishment","Punishment of Treason Clause"]],"by":{"0":"2, 3, 4, 6, 12"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(2)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§551. Definitions","tname":"Government Organization and Employees","by":{"0":"17, 17"}},{"t":"usc","label":"5 U.S.C. § 556","url":"https://www.law.cornell.edu/uscode/text/5/556","subs":["(C)"],"by":{"0":"18"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(b)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"17"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"0":"17"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","by":{"0":"18"}},{"t":"usc","label":"30 U.S.C. § 932","url":"https://www.law.cornell.edu/uscode/text/30/932","subs":["(k)"],"stext":{"head":"§932. Failure to meet workmen's compensation requirements","paras":[[0,"(a) Benefits; applicability of Longshore and Harbor Workers' Compensation Act; promulgation of regulations"],[0,"Subject to section 28(h)(1) of the Longshore and Harbor Workers' Compensation Act Amendments of 1984, during any period after December 31, 1973, in which a State workmen's compensation law is not included on the list published by the Secretary under section 931(b) of this title, the provisions of Public Law 803, 69th Congress (44 Stat. 1424, approved March 4, 1927), as amended [33 U.S.C. 901 et seq.], and as it may be amended from time to time (other than the provisions contained in sections 1, 2, 3, 4,,1 8, 9, 10, 12, 13, 29, 30, 31, 32, 33, 37, 38, 41, 43, 44, 45, 46, 47, 48, 49, 50, and 51 thereof) [33 U.S.C. 901, 902, 903, 904, 908, 909, 910, 912, 913, 929, 930, 931, 932, 933, 937, 938, 941, 943, 944, 945, 946, 947, 948, 948a, 949, 950], shall (except as otherwise provided in this subsection or by regulations of the Secretary and except that references in such Act to the employer shall be considered to refer to the trustees of the fund, as the Secretary considers appropriate and as is consistent with the provisions of section 9501(d) of title 26), be applicable to each operator of a coal mine in such State with respect to death or total disability due to pneumoconiosis arising out of employment in such mine, or with respect to entitlements established in paragraph (5) of section 921(c) of this title. In administering this part, the Secretary is authorized to prescribe in the Federal Register such additional provisions, not inconsistent with those specifically excluded by this subsection, as he deems necessary to provide for the payment of benefits by such operator to persons entitled thereto as provided in this part and thereafter those provisions shall be applicable to such operator."],[0,"(b) Liability of operators"],[0,"During any such period each such operator shall be liable for and shall secure the payment of benefits, as provided in this section and section 933 of this title. An employer, other than an operator of a coal mine, shall not be required to secure the payment of such benefits with respect to any employee of such employer to the extent such employee is engaged in the transportation of coal or in coal mine construction. Upon determination by the Secretary of the eligibility of the employee, the Secretary may require such employer to secure a bond or otherwise guarantee the payment of such benefits to the employee."],[0,"(c) Persons entitled to benefits"],[0,"Benefits shall be paid during such period by each such operator under this section to the categories of persons entitled to benefits under section 922(a) of this title in accordance with the regulations of the Secretary applicable under this section: Provided, That, except as provided in subsection (i) of this section, no benefit shall be payable by any operator on account of death or total disability due to pneumoconiosis (1) which did not arise, at least in part, out of employment in a mine during a period after December 31, 1969, when it was operated by such operator; or (2) which was the subject of a claim denied before March 1, 1978, and which is or has been approved in accordance with the provisions of section 945 2 of this title."],[0,"(d) Monthly payments; amounts; accrual of interest"],[0,"Benefits payable under this section shall be paid on a monthly basis and, except as otherwise provided in this section, such payments shall be equal to the amounts specified in section 922(a) of this title. If payment is not made within the time required, interest shall accrue to such amounts at the rates set forth in section 934(b)(5) of this title for interest owed to the fund. With respect to payments withheld pending final adjudication of liability, in the case of claims filed on or after the effective date of the Black Lung Benefits Amendments of 1981, such interest shall commence to accumulate 30 days after the date of the determination that such an award should be made."],[0,"(e) Conditions upon payment"],[0,"No payment of benefits shall be required under this section:"],[1,"(1) except pursuant to a claim filed therefor in such manner, in such form, and containing such information, as the Secretary shall by regulation prescribe; or"],[1,"(2) for any period prior to January 1, 1974."],[0,"(f) Limitation on filing of claims"],[0,"Any claim for benefits by a miner under this section shall be filed within three years after whichever of the following occurs later—"],[1,"(1) a medical determination of total disability due to pneumoconiosis; or"],[1,"(2) March 1, 1978."],[0,"(g) Reduction of monthly benefits"],[0,"The amount of benefits payable under this section shall be reduced, on a monthly or other appropriate basis, by the amount of any compensation received under or pursuant to any Federal or State workmen's compensation law because of death or disability due to pneumoconiosis. In addition, the amount of benefits payable under this section with respect to any claim filed on or after the effective date of the Black Lung Benefits Amendments of 1981 shall be reduced, on a monthly or other appropriate basis, by the amount by which such benefits would be reduced on account of excess earnings of such miner under section 403(b) through (l) of title 42 if the amount paid were a benefit payable under section 402 of title 42."],[0,"(h) Promulgation of regulations"],[0,"The Secretary of Labor shall by regulation establish standards, which may include appropriate presumptions, for determining whether pneumoconiosis arose out of employment in a particular coal mine or mines. The Secretary may also, by regulation, establish standards for apportioning liability for benefits under this subsection among more than one operator, where such apportionment is appropriate."],[0,"(i) Subsequent operators' liability for benefit payments"],[0,"(1) During any period in which this section is applicable to the operator of a coal mine who on or after January 1, 1970, acquired such mine or substantially all the assets thereof, from a person (hereinafter in this subsection referred to as a \"prior operator\") who was an operator of such mine, or owner of such assets on or after January 1, 1970, such operator shall be liable for and shall, in accordance with section 933 of this title, secure the payment of all benefits which would have been payable by the prior operator under this section with respect to miners previously employed by such prior operator as if the acquisition had not occurred and the prior operator had continued to be an operator of a coal mine."],[0,"(2) Nothing in this subsection shall relieve any prior operator of any liability under this section."],[0,"(3)(A) For purposes of paragraph (1) of this subsection, the provisions of this paragraph shall apply to corporate reorganizations, liquidations, and such other transactions as are specified in this paragraph."],[0,"(B) If an operator ceases to exist by reason of a reorganization or other transaction or series of transactions which involves a change in identity, form, or place of business or organization, however effected, the successor operator or other corporate or business entity resulting from such reorganization or other change shall be treated as the operator to whom this section applies."],[0,"(C) If an operator ceases to exist by reason of a liquidation into a parent or successor corporation, the parent or successor corporation shall be treated as the operator to whom this section applies."],[0,"(D) If an operator ceases to exist by reason of a sale of substantially all his or her assets, or as the result of a merger, consolidation, or division, the successor operator, corporation, or other business entity shall be treated as the operator to whom this section applies."],[0,"(4) In any case in which there is a determination under section 9501(d) of title 26 that no operator is liable for the payment of benefits to a claimant, nothing in this subsection may be construed to require the payment of benefits to a claimant by or on behalf of any operator."],[0,"(j) Failure of operators to secure benefits"],[0,"Notwithstanding the provisions of this section, section 9501 of title 26 shall govern the payment of benefits in cases—"],[1,"(1) described in section 9501(d)(1) of title 26;"],[1,"(2) in which the miner's last coal mine employment was before January 1, 1970; or"],[1,"(3) in which there was a claim denied before March 1, 1978, and such claim is or has been approved in accordance with the provisions of section 945 2 of this title."],[0,"(k) Secretary as party in claim proceedings"],[0,"The Secretary shall be a party in any proceeding relative to a claim for benefits under this part."],[0,"(l) Filing of new claims or refiling or revalidation of claims of miners already determined eligible at time of death"],[0,"In no case shall the eligible survivors of a miner who was determined to be eligible to receive benefits under this subchapter at the time of his or her death be required to file a new claim for benefits, or refile or otherwise revalidate the claim of such miner,.3"]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/30/932?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§932. Failure to meet workmen's compensation requirements","tname":"Mineral Lands and Mining","by":{"0":"14, 15"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"2, 3"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","by":{"0":"3"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"3"}},{"t":"usc","label":"33 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/33/901","stext":{"head":"§901. Short title","paras":[[0,"This chapter may be cited as \"Longshore and Harbor Workers' Compensation Act.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/901?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§901. Short title","tname":"Navigation and Navigable Waters","by":{"0":"1"}},{"t":"usc","label":"33 U.S.C. § 902","url":"https://www.law.cornell.edu/uscode/text/33/902","subs":["(1)","(4)","(6)"],"stext":{"head":"§902. Definitions","paras":[[0,"When used in this chapter—"],[1,"(1) The term \"person\" means individual, partnership, corporation, or association."],[1,"(2) The term \"injury\" means accidental injury or death arising out of and in the course of employment, and such occupational disease or infection as arises naturally out of such employment or as naturally or unavoidably results from such accidental injury, and includes an injury caused by the willful act of a third person directed against an employee because of his employment."],[1,"(3) The term \"employee\" means any person engaged in maritime employment, including any longshoreman or other person engaged in longshoring operations, and any harbor-worker including a ship repairman, shipbuilder, and ship-breaker, but such term does not include—"],[2,"(A) individuals employed exclusively to perform office clerical, secretarial, security, or data processing work;"],[2,"(B) individuals employed by a club, camp, recreational operation, restaurant, museum, or retail outlet;"],[2,"(C) individuals employed by a marina and who are not engaged in construction, replacement, or expansion of such marina (except for routine maintenance);"],[2,"(D) individuals who (i) are employed by suppliers, transporters, or vendors, (ii) are temporarily doing business on the premises of an employer described in paragraph (4), and (iii) are not engaged in work normally performed by employees of that employer under this chapter;"],[2,"(E) aquaculture workers;"],[2,"(F) individuals employed to build any recreational vessel under sixty-five feet in length, or individuals employed to repair any recreational vessel, or to dismantle any part of a recreational vessel in connection with the repair of such vessel;"],[2,"(G) a master or member of a crew of any vessel; or"],[2,"(H) any person engaged by a master to load or unload or repair any small vessel under eighteen tons net;"],[1,"if individuals described in clauses (A) through (F) are subject to coverage under a State workers' compensation law."],[1,"(4) The term \"employer\" means an employer any of whose employees are employed in maritime employment, in whole or in part, upon the navigable waters of the United States (including any adjoining pier, wharf, dry dock, terminal, building way, marine railway, or other adjoining area customarily used by an employer in loading, unloading, repairing, or building a vessel)."],[1,"(5) The term \"carrier\" means any person or fund authorized under section 932 of this title to insure under this chapter and includes self-insurers."],[1,"(6) The term \"Secretary\" means the Secretary of Labor."],[1,"(7) The term \"deputy commissioner\" means the deputy commissioner having jurisdiction in respect of an injury or death."],[1,"(8) The term \"State\" includes a Territory and the District of Columbia."],[1,"(9) The term \"United States\" when used in a geographical sense means the several States and Territories and the District of Columbia, including the territorial waters thereof."],[1,"(10) \"Disability\" means incapacity because of injury to earn the wages which the employee was receiving at the time of injury in the same or any other employment; but such term shall mean permanent impairment, determined (to the extent covered thereby) under the guides to the evaluation of permanent impairment promulgated and modified from time to time by the American Medical Association, in the case of an individual whose claim is described in section 910(d)(2) of this title."],[1,"(11) \"Death\" as a basis for a right to compensation means only death resulting from an injury."],[1,"(12) \"Compensation\" means the money allowance payable to an employee or to his dependents as provided for in this chapter, and includes funeral benefits provided therein."],[1,"(13) The term \"wages\" means the money rate at which the service rendered by an employee is compensated by an employer under the contract of hiring in force at the time of the injury, including the reasonable value of any advantage which is received from the employer and included for purposes of any withholding of tax under subtitle C of title 26 (relating to employment taxes). The term wages does not include fringe benefits, including (but not limited to) employer payments for or contributions to a retirement, pension, health and welfare, life insurance, training, social security or other employee or dependent benefit plan for the employee's or dependent's benefit, or any other employee's dependent entitlement."],[1,"(14) \"Child\" shall include a posthumous child, a child legally adopted prior to the injury of the employee, a child in relation to whom the deceased employee stood in loco parentis for at least one year prior to the time of injury, and a stepchild or acknowledged illegitimate child dependent upon the deceased, but does not include married children unless wholly dependent on him. \"Grandchild\" means a child as above defined of a child as above defined. \"Brother\" and \"sister\" includes stepbrothers and stepsisters, half brothers and half sisters, and brothers and sisters by adoption, but does not include married brothers nor married sisters unless wholly dependent on the employee. \"Child\", \"grandchild\", \"brother\", and \"sister\" include only a person who is under eighteen years of age, or who, though eighteen years of age or over, is (1) wholly dependent upon the employee and incapable of self-support by reason of mental or physical disability, or (2) a student as defined in paragraph (19) of this section."],[1,"(15) The term \"parent\" includes step-parents and parents by adoption, parents-in-law, and any person who for more than three years prior to the death of the deceased employee stood in the place of a parent to him, if dependent on the injured employee."],[1,"(16) The terms \"widow or widower\" includes only the decedent's wife or husband living with or dependent for support upon him or her at the time of his or her death; or living apart for justifiable cause or by reason of his or her desertion at such time."],[1,"(17) The terms \"adoption\" or \"adopted\" mean legal adoption prior to the time of the injury."],[1,"(18) The term \"student\" means a person regularly pursuing a full-time course of study or training at an institution which is—"],[2,"(A) a school or college or university operated or directly supported by the United States, or by any State or local government or political subdivision thereof,"],[2,"(B) a school or college or university which has been accredited by a State or by a State recognized or nationally recognized accrediting agency or body."],[2,"(C) a school or college or university not so accredited but whose credits are accepted, on transfer, by not less than three institutions which are so accredited, for credit on the same basis as if transferred from an institution so accredited, or"],[2,"(D) an additional type of educational or training institution as defined by the Secretary,"],[1,"but not after he reaches the age of twenty-three or has completed four years of education beyond the high school level, except that, where his twenty-third birthday occurs during a semester or other enrollment period, he shall continue to be considered a student until the end of such semester or other enrollment period. A child shall not be deemed to have ceased to be a student during any interim between school years if the interim does not exceed five months and if he shows to the satisfaction of the Secretary that he has a bona fide intention of continuing to pursue a full-time course of education or training during the semester or other enrollment period immediately following the interim or during periods of reasonable duration during which, in the judgment of the Secretary, he is prevented by factors beyond his control from pursuing his education. A child shall not be deemed to be a student under this chapter during a period of service in the Armed Forces of the United States."],[1,"(19) The term \"national average weekly wage\" means the national average weekly earnings of production or nonsupervisory workers on private nonagricultural payrolls."],[1,"(20) The term \"Board\" shall mean the Benefits Review Board."],[1,"(21) Unless the context requires otherwise, the term \"vessel\" means any vessel upon which or in connection with which any person entitled to benefits under this chapter suffers injury or death arising out of or in the course of his employment, and said vessel's owner, owner pro hac vice, agent, operator, charter or bare boat charterer, master, officer, or crew member."],[1,"(22) The singular includes the plural and the masculine includes the feminine and neuter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/902?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§902. Definitions","tname":"Navigation and Navigable Waters","by":{"0":"15, 16, 15"}},{"t":"usc","label":"33 U.S.C. § 906","url":"https://www.law.cornell.edu/uscode/text/33/906","stext":{"head":"§906. Compensation","paras":[[0,"(a) Time for commencement"],[0,"No compensation shall be allowed for the first three days of the disability, except the benefits provided for in section 907 of this title: Provided, however, That in case the injury results in disability of more than fourteen days the compensation shall be allowed from the date of the disability."],[0,"(b) Maximum rate of compensation"],[0,"(1) Compensation for disability or death (other than compensation for death required by this chapter to be paid in a lump sum) shall not exceed an amount equal to 200 per centum of the applicable national average weekly wage, as determined by the Secretary under paragraph (3)."],[0,"(2) Compensation for total disability shall not be less than 50 per centum of the applicable national average weekly wage determined by the Secretary under paragraph (3), except that if the employee's average weekly wages as computed under section 910 of this title are less than 50 per centum of such national average weekly wage, he shall receive his average weekly wages as compensation for total disability."],[0,"(3) As soon as practicable after June 30 of each year, and in any event prior to October 1 of such year, the Secretary shall determine the national average weekly wage for the three consecutive calendar quarters ending June 30. Such determination shall be the applicable national average weekly wage for the period beginning with October 1 of that year and ending with September 30 of the next year. The initial determination under this paragraph shall be made as soon as practicable after October 27, 1972."],[0,"(c) Applicability of determinations"],[0,"Determinations under subsection (b)(3) with respect to a period shall apply to employees or survivors currently receiving compensation for permanent total disability or death benefits during such period, as well as those newly awarded compensation during such period."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/906?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§906. Compensation","tname":"Navigation and Navigable Waters","by":{"0":"2"}},{"t":"usc","label":"33 U.S.C. § 907","url":"https://www.law.cornell.edu/uscode/text/33/907","subs":["(a)","(b)"],"stext":{"head":"§907. Medical services and supplies","paras":[[0,"(a) General requirement"],[0,"The employer shall furnish such medical, surgical, and other attendance or treatment, nurse and hospital service, medicine, crutches, and apparatus, for such period as the nature of the injury or the process of recovery may require."],[0,"(b) Physician selection; administrative supervision; change of physicians and hospitals"],[0,"The employee shall have the right to choose an attending physician authorized by the Secretary to provide medical care under this chapter as hereinafter provided. If, due to the nature of the injury, the employee is unable to select his physician and the nature of the injury requires immediate medical treatment and care, the employer shall select a physician for him. The Secretary shall actively supervise the medical care rendered to injured employees, shall require periodic reports as to the medical care being rendered to injured employees, shall have authority to determine the necessity, character, and sufficiency of any medical aid furnished or to be furnished, and may, on his own initiative or at the request of the employer, order a change of physicians or hospitals when in his judgment such change is desirable or necessary in the interest of the employee or where the charges exceed those prevailing within the community for the same or similar services or exceed the provider's customary charges. Change of physicians at the request of employees shall be permitted in accordance with regulations of the Secretary."],[0,"(c) Physicians and health care providers not authorized to render medical care or provide medical services"],[0,"(1)(A) The Secretary shall annually prepare a list of physicians and health care providers in each compensation district who are not authorized to render medical care or provide medical services under this chapter. The names of physicians and health care providers contained on the list required under this subparagraph shall be made available to employees and employers in each compensation district through posting and in such other forms as the Secretary may prescribe."],[0,"(B) Physicians and health care providers shall be included on the list of those not authorized to provide medical care and medical services pursuant to subparagraph (A) when the Secretary determines under this section, in accordance with the procedures provided in subsection (j), that such physician or health care provider—"],[1,"(i) has knowingly and willfully made, or caused to be made, any false statement or misrepresentation of a material fact for use in a claim for compensation or claim for reimbursement of medical expenses under this chapter;"],[1,"(ii) has knowingly and willfully submitted, or caused to be submitted, a bill or request for payment under this chapter containing a charge which the Secretary finds to be substantially in excess of the charge for the service, appliance, or supply prevailing within the community or in excess of the provider's customary charges, unless the Secretary finds there is good cause for the bill or request containing the charge;"],[1,"(iii) has knowingly and willfully furnished a service, appliance, or supply which is determined by the Secretary to be substantially in excess of the need of the recipient thereof or to be of a quality which substantially fails to meet professionally recognized standards;"],[1,"(iv) has been convicted under any criminal statute (without regard to pending appeal thereof) for fraudulent activities in connection with any Federal or State program for which payments are made to physicians or providers of similar services, appliances, or supplies; or"],[1,"(v) has otherwise been excluded from participation in such program."],[0,"(C) Medical services provided by physicians or health care providers who are named on the list published by the Secretary pursuant to subparagraph (A) of this section 1 shall not be reimbursable under this chapter; except that the Secretary shall direct the reimbursement of medical claims for services rendered by such physicians or health care providers in cases where the services were rendered in an emergency."],[0,"(D) A determination under subparagraph (B) shall remain in effect for a period of not less than three years and until the Secretary finds and gives notice to the public that there is reasonable assurance that the basis for the determination will not reoccur."],[0,"(E) A provider of a service, appliance, or supply shall provide to the Secretary such information and certification as the Secretary may require to assure that this subsection is enforced."],[0,"(2) Whenever the employer or carrier acquires knowledge of the employee's injury, through written notice or otherwise as prescribed by the chapter, the employer or carrier shall forthwith authorize medical treatment and care from a physician selected by an employee pursuant to subsection (b). An employee may not select a physician who is on the list required by paragraph (1) of this subsection. An employee may not change physicians after his initial choice unless the employer, carrier, or deputy commissioner has given prior consent for such change. Such consent shall be given in cases where an employee's initial choice was not of a specialist whose services are necessary for and appropriate to the proper care and treatment of the compensable injury or disease. In all other cases, consent may be given upon a showing of good cause for change."],[0,"(d) Request of treatment or services prerequisite to recovery of expenses; formal report of injury and treatment; suspension of compensation for refusal of treatment or examination; justification"],[0,"(1) An employee shall not be entitled to recover any amount expended by him for medical or other treatment or services unless—"],[1,"(A) the employer shall have refused or neglected a request to furnish such services and the employee has complied with subsections (b) and (c) and the applicable regulations; or"],[1,"(B) the nature of the injury required such treatment and services and the employer or his superintendent or foreman having knowledge of such injury shall have neglected to provide or authorize same."],[0,"(2) No claim for medical or surgical treatment shall be valid and enforceable against such employer unless, within ten days following the first treatment, the physician giving such treatment furnishes to the employer and the deputy commissioner a report of such injury or treatment, on a form prescribed by the Secretary. The Secretary may excuse the failure to furnish such report within the ten-day period whenever he finds it to be in the interest of justice to do so."],[0,"(3) The Secretary may, upon application by a party in interest, make an award for the reasonable value of such medical or surgical treatment so obtained by the employee."],[0,"(4) If at any time the employee unreasonably refuses to submit to medical or surgical treatment, or to an examination by a physician selected by the employer, the Secretary or administrative law judge may, by order, suspend the payment of further compensation during such time as such refusal continues, and no compensation shall be paid at any time during the period of such suspension, unless the circumstances justified the refusal."],[0,"(e) Physical examination; medical questions; report of physical impairment; review or reexamination; costs"],[0,"In the event that medical questions are raised in any case, the Secretary shall have the power to cause the employee to be examined by a physician employed or selected by the Secretary and to obtain from such physician a report containing his estimate of the employee's physical impairment and such other information as may be appropriate. Any party who is dissatisfied with such report may request a review or reexamination of the employee by one or more different physicians employed or selected by the Secretary. The Secretary shall order such review or reexamination unless he finds that it is clearly unwarranted. Such review or reexamination shall be completed within two weeks from the date ordered unless the Secretary finds that because of extraordinary circumstances a longer period is required. The Secretary shall have the power in his discretion to charge the cost of examination or review under this subsection to the employer, if he is a self-insurer, or to the insurance company which is carrying the risk, in appropriate cases, or to the special fund in section 944 of this title."],[0,"(f) Place of examination; exclusion of physicians other than examining physician of Secretary; good cause for conclusions of other physicians respecting impairment; examination by employer's physician; suspension of proceedings and compensation for refusal of examination"],[0,"An employee shall submit to a physical examination under subsection (e) at such place as the Secretary may require. The place, or places, shall be designated by the Secretary and shall be reasonably convenient for the employee. No physician selected by the employer, carrier, or employee shall be present at or participate in any manner in such examination, nor shall conclusions of such physicians as to the nature or extent of impairment or the cause of impairment be available to the examining physician unless otherwise ordered, for good cause, by the Secretary. Such employer or carrier shall, upon request, be entitled to have the employee examined immediately thereafter and upon the same premises by a qualified physician or physicians in the presence of such physician as the employee may select, if any. Proceedings shall be suspended and no compensation shall be payable for any period during which the employee may refuse to submit to examination."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/907?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§907. Medical services and supplies","tname":"Navigation and Navigable Waters","by":{"0":"5, 5"}},{"t":"usc","label":"33 U.S.C. § 908","url":"https://www.law.cornell.edu/uscode/text/33/908","subs":["(f)","(i)"],"stext":{"head":"§908. Compensation for disability","paras":[[0,"Compensation for disability shall be paid to the employee as follows:"],[0,"(a) Permanent total disability: In case of total disability adjudged to be permanent 662/3 per centum of the average weekly wages shall be paid to the employee during the continuance of such total disability. Loss of both hands, or both arms, or both feet, or both legs, or both eyes, or of any two thereof shall, in the absence of conclusive proof to the contrary, constitute permanent total disability. In all other cases permanent total disability shall be determined in accordance with the facts."],[0,"(b) Temporary total disability: In case of disability total in character but temporary in quality 662/3 per centum of the average weekly wages shall be paid to the employee during the continuance thereof."],[0,"(c) Permanent partial disability: In case of disability partial in character but permanent in quality the compensation shall be 662/3 per centum of the average weekly wages, which shall be in addition to compensation for temporary total disability or temporary partial disability paid in accordance with subsection (b) or subsection (e) of this section, respectively, and shall be paid to the employee, as follows:"],[1,"(1) Arm lost, three hundred and twelve weeks' compensation."],[1,"(2) Leg lost, two hundred and eighty-eight weeks' compensation."],[1,"(3) Hand lost, two hundred and forty-four weeks' compensation."],[1,"(4) Foot lost, two hundred and five weeks' compensation."],[1,"(5) Eye lost, one hundred and sixty weeks' compensation."],[1,"(6) Thumb lost, seventy-five weeks' compensation."],[1,"(7) First finger lost, forty-six weeks' compensation."],[1,"(8) Great toe lost, thirty-eight weeks' compensation."],[1,"(9) Second finger lost, thirty weeks' compensation."],[1,"(10) Third finger lost, twenty-five weeks' compensation."],[1,"(11) Toe other than great toe lost, sixteen weeks' compensation."],[1,"(12) Fourth finger lost, fifteen weeks' compensation."],[1,"(13) Loss of hearing:"],[2,"(A) Compensation for loss of hearing in one ear, fifty-two weeks."],[2,"(B) Compensation for loss of hearing in both ears, two-hundred weeks."],[2,"(C) An audiogram shall be presumptive evidence of the amount of hearing loss sustained as of the date thereof, only if (i) such audiogram was administered by a licensed or certified audiologist or a physician who is certified in otolaryngology, (ii) such audiogram, with the report thereon, was provided to the employee at the time it was administered, and (iii) no contrary audiogram made at that time is produced."],[2,"(D) The time for filing a notice of injury, under section 912 of this title, or a claim for compensation, under section 913 of this title, shall not begin to run in connection with any claim for loss of hearing under this section, until the employee has received an audiogram, with the accompanying report thereon, which indicates that the employee has suffered a loss of hearing."],[2,"(E) Determinations of loss of hearing shall be made in accordance with the guides for the evaluation of permanent impairment as promulgated and modified from time to time by the American Medical Association."],[1,"(14) Phalanges: Compensation for loss of more than one phalange of a digit shall be the same as for loss of the entire digit. Compensation for loss of the first phalange shall be one-half of the compensation for loss of the entire digit."],[1,"(15) Amputated arm or leg: Compensation for an arm or a leg, if amputated at or above the elbow or the knee, shall be the same as for a loss of the arm or leg; but, if amputated between the elbow and the wrist or the knee and the ankle, shall be the same as for loss of a hand or foot."],[1,"(16) Binocular vision or per centum of vision: Compensation for loss of binocular vision or for 80 per centum or more of the vision of an eye shall be the same as for loss of the eye."],[1,"(17) Two or more digits: Compensation for loss of two or more digits, or one or more phalanges of two or more digits, of a hand or foot may be proportioned to the loss of use of the hand or foot occasioned thereby, but shall not exceed the compensation for loss of a hand or foot."],[1,"(18) Total loss of use: Compensation for permanent total loss of use of a member shall be the same as for loss of the member."],[1,"(19) Partial loss or partial loss of use: Compensation for permanent partial loss or loss of use of a member may be for proportionate loss or loss of use of the member."],[1,"(20) Disfigurement: Proper and equitable compensation not to exceed $7,500 shall be awarded for serious disfigurement of the face, head, or neck or of other normally exposed areas likely to handicap the employee in securing or maintaining employment."],[1,"(21) Other cases: In all other cases in the class of disability, the compensation shall be 662/3 per centum of the difference between the average weekly wages of the employee and the employee's wage-earning capacity thereafter in the same employment or otherwise, payable during the continuance of partial disability."],[1,"(22) In any case in which there shall be a loss of, or loss of use of, more than one member or parts of more than one member set forth in paragraphs (1) to (19) of this subsection, not amounting to permanent total disability, the award of compensation shall be for the loss of, or loss of use of, each such member or part thereof, which awards shall run consecutively, except that where the injury affects only two or more digits of the same hand or foot, paragraph (17) of this subsection shall apply."],[1,"(23) Notwithstanding paragraphs (1) through (22), with respect to a claim for permanent partial disability for which the average weekly wages are determined under section 910(d)(2) of this title, the compensation shall be 662/3 per centum of such average weekly wages multiplied by the percentage of permanent impairment, as determined under the guides referred to in section 902(10) of this title, payable during the continuance of such impairment."],[0,"(d)(1) If an employee who is receiving compensation for permanent partial disability pursuant to subsection (c)(1)–(20) dies from causes other than the injury, the total amount of the award unpaid at the time of death shall be payable to or for the benefit of his survivors, as follows:"],[1,"(A) if the employee is survived only by a widow or widower, such unpaid amount of the award shall be payable to such widow or widower,"],[1,"(B) if the employee is survived only by a child or children, such unpaid amount of the award shall be paid to such child or children in equal shares,"],[1,"(C) if the employee is survived by a widow or widower and a child or children, such unpaid amount of the award shall be payable to such survivors in equal shares,"],[1,"(D) if there be no widow or widower and no surviving child or children, such unpaid amount of the award shall be paid to the survivors specified in section 909(d) of this title (other than a wife, husband, or child); and the amount to be paid each such survivor shall be determined by multiplying such unpaid amount of the award by the appropriate percentage specified in section 909(d) of this title, but if the aggregate amount to which all such survivors are entitled, as so determined, is less than such unpaid amount of the award, the excess amount shall be divided among such survivors pro rata according to the amount otherwise payable to each under this subparagraph."],[0,"(2) Notwithstanding any other limitation in section 909 of this title, the total amount of any award for permanent partial disability pursuant to subsection (c)(1)–(20) unpaid at time of death shall be payable in full in the appropriate distribution."],[0,"(3) An award for disability may be made after the death of the injured employee. Except where compensation is payable under subsection (c)(21) if there be no survivors as prescribed in this section, then the compensation payable under this subsection shall be paid to the special fund established under section 944(a) of this title."],[0,"(e) Temporary partial disability: In case of temporary partial disability resulting in decrease of earning capacity the compensation shall be two-thirds of the difference between the injured employee's average weekly wages before the injury and his wage-earning capacity after the injury in the same or another employment, to be paid during the continuance of such disability, but shall not be paid for a period exceeding five years."],[0,"(f) Injury increasing disability:"],[1,"(1) In any case in which an employee having an existing permanent partial disability suffers injury, the employer shall provide compensation for such disability as is found to be attributable to that injury based upon the average weekly wages of the employee at the time of the injury. If following an injury falling within the provisions of subsection (c)(1)–(20), the employee is totally and permanently disabled, and the disability is found not to be due solely to that injury, the employer shall provide compensation for the applicable prescribed period of weeks provided for in that section for the subsequent injury, or for one hundred and four weeks, whichever is the greater, except that, in the case of an injury falling within the provisions of subsection (c)(13), the employer shall provide compensation for the lesser of such periods. In all other cases of total permanent disability or of death, found not to be due solely to that injury, of an employee having an existing permanent partial disability, the employer shall provide in addition to compensation under subsections (b) and (e) of this section, compensation payments or death benefits for one hundred and four weeks only. If following an injury falling within the provisions of subsection (c)(1)–(20), the employee has a permanent partial disability and the disability is found not to be due solely to that injury, and such disability is materially and substantially greater than that which would have resulted from the subsequent injury alone, the employer shall provide compensation for the applicable period of weeks provided for in that section for the subsequent injury, or for one hundred and four weeks, whichever is the greater, except that, in the case of an injury falling within the provisions of subsection (c)(13), the employer shall provide compensation for the lesser of such periods."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/908?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§908. Compensation for disability","tname":"Navigation and Navigable Waters","by":{"0":"2, 17, 3, 5, 11"}},{"t":"usc","label":"33 U.S.C. § 909","url":"https://www.law.cornell.edu/uscode/text/33/909","by":{"0":"2"}},{"t":"usc","label":"33 U.S.C. § 910","url":"https://www.law.cornell.edu/uscode/text/33/910","by":{"0":"2"}},{"t":"usc","label":"33 U.S.C. § 915","url":"https://www.law.cornell.edu/uscode/text/33/915","subs":["(b)"],"by":{"0":"3"}},{"t":"usc","label":"33 U.S.C. § 916","url":"https://www.law.cornell.edu/uscode/text/33/916","by":{"0":"3"}},{"t":"usc","label":"33 U.S.C. § 919","url":"https://www.law.cornell.edu/uscode/text/33/919","subs":["(d)"],"stext":{"head":"§919. Procedure in respect of claims","paras":[[0,"(a) Filing of claim"],[0,"Subject to the provisions of section 913 of this title a claim for compensation may be filed with the deputy commissioner in accordance with regulations prescribed by the Secretary at any time after the first seven days of disability following any injury, or at any time after death, and the deputy commissioner shall have full power and authority to hear and determine all questions in respect of such claim."],[0,"(b) Notice of claim"],[0,"Within ten days after such claim is filed the deputy commissioner, in accordance with regulations prescribed by the Secretary, shall notify the employer and any other person (other than the claimant), whom the deputy commissioner considers an interested party, that a claim has been filed. Such notice may be served personally upon the employer or other person, or sent to such employer or person by registered mail."],[0,"(c) Investigations; order for hearing; notice; rejection or award"],[0,"The deputy commissioner shall make or cause to be made such investigations as he considers necessary in respect of the claim, and upon application of any interested party shall order a hearing thereon. If a hearing on such claim is ordered the deputy commissioner shall give the claimant and other interested parties at least ten days' notice of such hearing, served personally upon the claimant and other interested parties or sent to such claimant and other interested parties by registered mail or by certified mail, and shall within twenty days after such hearing is had, by order, reject the claim or make an award in respect of the claim. If no hearing is ordered within twenty days after notice is given as provided in subsection (b), the deputy commissioner shall, by order, reject the claim or make an award in respect of the claim."],[0,"(d) Provisions governing conduct of hearing; administrative law judges"],[0,"Notwithstanding any other provisions of this chapter, any hearing held under this chapter shall be conducted in accordance with the provisions of section 554 of title 5. Any such hearing shall be conducted by a 1 administrative law judge qualified under section 3105 of that title. All powers, duties, and responsibilities vested by this chapter, on October 27, 1972, in the deputy commissioners with respect to such hearings shall be vested in such administrative law judges."],[0,"(e) Filing and mailing of order rejecting claim or making award"],[0,"The order rejecting the claim or making the award (referred to in this chapter as a compensation order) shall be filed in the office of the deputy commissioner, and a copy thereof shall be sent by registered mail or by certified mail to the claimant and to the employer at the last known address of each."],[0,"(f) Awards after death of employee"],[0,"An award of compensation for disability may be made after the death of an injured employee."],[0,"(g) Transfer of case"],[0,"At any time after a claim has been filed with him, the deputy commissioner may, with the approval of the Secretary, transfer such case to any other deputy commissioner for the purpose of making investigation, taking testimony, making physical examinations or taking such other necessary action therein as may be directed."],[0,"(h) Physical examination of injured employee"],[0,"An injured employee claiming or entitled to compensation shall submit to such physical examination by a medical officer of the United States or by a duly qualified physician designated or approved by the Secretary as the deputy commissioner may require. The place or places shall be reasonably convenient for the employee. Such physician or physicians as the employee, employer, or carrier may select and pay for may participate in an examination if the employee, employer, or carrier so requests. Proceedings shall be suspended and no compensation be payable for any period during which the employee may refuse to submit to examination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/919?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§919. Procedure in respect of claims","tname":"Navigation and Navigable Waters","by":{"0":"17"}},{"t":"usc","label":"33 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/33/921","subs":["(b)(1)","(b)(2)","(b)(3)","(b)(4)","(c)","(d)"],"stext":{"head":"§921. Review of compensation orders","paras":[[0,"(a) Effectiveness and finality of orders"],[0,"A compensation order shall become effective when filed in the office of the deputy commissioner as provided in section 919 of this title, and, unless proceedings for the suspension or setting aside of such order are instituted as provided in subsection (b) of this section, shall become final at the expiration of the thirtieth day thereafter."],[0,"(b) Benefits Review Board; establishment; members; chairman; quorum; voting; questions reviewable; record; conclusiveness of findings; stay of payments; remand"],[0,"(1) There is hereby established a Benefits Review Board which shall be composed of five members appointed by the Secretary from among individuals who are especially qualified to serve on such Board. The Secretary shall designate one of the members of the Board to serve as chairman. The Chairman shall have the authority, as delegated by the Secretary, to exercise all administrative functions necessary to operate the Board."],[0,"(2) For the purpose of carrying out its functions under this chapter, three members of the Board shall constitute a quorum and official action can be taken only on the affirmative vote of at least three members."],[0,"(3) The Board shall be authorized to hear and determine appeals raising a substantial question of law or fact taken by any party in interest from decisions with respect to claims of employees under this chapter and the extensions thereof. The Board's orders shall be based upon the hearing record. The findings of fact in the decision under review by the Board shall be conclusive if supported by substantial evidence in the record considered as a whole. The payment of the amounts required by an award shall not be stayed pending final decision in any such proceeding unless ordered by the Board. No stay shall be issued unless irreparable injury would otherwise ensue to the employer or carrier."],[0,"(4) The Board may, on its own motion or at the request of the Secretary, remand a case to the administrative law judge for further appropriate action. The consent of the parties in interest shall not be a prerequisite to a remand by the Board."],[0,"(5) Notwithstanding paragraphs (1) through (4), upon application of the Chairman of the Board, the Secretary may designate up to four Department of Labor administrative law judges to serve on the Board temporarily, for not more than one year. The Board is authorized to delegate to panels of three members any or all of the powers which the Board may exercise. Each such panel shall have no more than one temporary member. Two members shall constitute a quorum of a panel. Official adjudicative action may be taken only on the affirmative vote of at least two members of a panel. Any party aggrieved by a decision of a panel of the Board may, within thirty days after the date of entry of the decision, petition the entire permanent Board for review of the panel's decision. Upon affirmative vote of the majority of the permanent members of the Board, the petition shall be granted. The Board shall amend its Rules of Practice to conform with this paragraph. Temporary members, while serving as members of the Board, shall be compensated at the same rate of compensation as regular members."],[0,"(c) Court of appeals; jurisdiction; persons entitled to review; petition; record; determination and enforcement; service of process; stay of payments"],[0,"Any person adversely affected or aggrieved by a final order of the Board may obtain a review of that order in the United States court of appeals for the circuit in which the injury occurred, by filing in such court within sixty days following the issuance of such Board order a written petition praying that the order be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court, to the Board, and to the other parties, and thereupon the Board shall file in the court the record in the proceedings as provided in section 2112 of title 28. Upon such filing, the court shall have jurisdiction of the proceeding and shall have the power to give a decree affirming, modifying, or setting aside, in whole or in part, the order of the Board and enforcing same to the extent that such order is affirmed or modified. The orders, writs, and processes of the court in such proceedings may run, be served, and be returnable anywhere in the United States. The payment of the amounts required by an award shall not be stayed pending final decision in any such proceeding unless ordered by the court. No stay shall be issued unless irreparable injury would otherwise ensue to the employer or carrier. The order of the court allowing any stay shall contain a specific finding, based upon evidence submitted to the court and identified by reference thereto, that irreparable damage would result to the employer, and specifying the nature of the damage."],[0,"(d) District court; jurisdiction; enforcement of orders; application of beneficiaries of awards or deputy commissioner; process for compliance with orders"],[0,"If any employer or his officers or agents fails to comply with a compensation order making an award, that has become final, any beneficiary of such award or the deputy commissioner making the order, may apply for the enforcement of the order to the Federal district court for the judicial district in which the injury occurred (or to the United States District Court for the District of Columbia if the injury occurred in the District). If the court determines that the order was made and served in accordance with law, and that such employer or his officers or agents have failed to comply therewith, the court shall enforce obedience to the order by writ of injunction or by other proper process, mandatory or otherwise, to enjoin upon such person and his officers and agents compliance with the order."],[0,"(e) Institution of proceedings for suspension, setting aside, or enforcement of compensation orders"],[0,"Proceedings for suspending, setting aside, or enforcing a compensation order, whether rejecting a claim or making an award, shall not be instituted otherwise than as provided in this section and section 918 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/921?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§921. Review of compensation orders","tname":"Navigation and Navigable Waters","by":{"0":"9, 9, 10, 13, 6, 7,13, 15, 16, 17, 18, 3, 6"}},{"t":"usc","label":"33 U.S.C. § 921a","url":"https://www.law.cornell.edu/uscode/text/33/921a","by":{"0":"11, 13"}},{"t":"usc","label":"33 U.S.C. § 939","url":"https://www.law.cornell.edu/uscode/text/33/939","subs":["(a)","(c)(1)"],"stext":{"head":"§939. Administration by Secretary","paras":[[0,"(a) Prescribing rules and regulations; appointing and fixing compensation of employees; making expenditures"],[0,"Except as otherwise specifically provided, the Secretary shall administer the provisions of this chapter, and for such purpose the Secretary is authorized (1) to make such rules and regulations; (2) to appoint and fix the compensation of such temporary technical assistants and medical advisers, and, subject to the provisions of the civil service laws, to appoint, and, in accordance with chapter 51 and subchapter III of chapter 53 of title 5, to fix the compensation of such deputy commissioners (except deputy commissioners appointed under subsection (a) of section 940 of this title) and other officers and employees; and (3) to make such expenditures (including expenditures for personal services and rent at the seat of government and elsewhere, for law books, books of reference, periodicals, and for printing and binding) as may be necessary in the administration of this chapter. All expenditures of the Secretary in the administration of this chapter shall be allowed and paid as provided in section 945 1 of this title upon the presentation of itemized vouchers therefor approved by the Secretary."],[0,"(b) Establishing compensation districts"],[0,"The Secretary shall establish compensation districts, to include the high seas and the areas within the United States to which this chapter applies, and shall assign to each such district one or more deputy commissioners, as the Secretary deems advisable. Judicial proceedings under sections 918 and 921 of this title in respect of any injury or death occurring on the high seas shall be instituted in the district court within whose territorial jurisdiction is located the office of the deputy commissioner having jurisdiction in respect of such injury or death (or in the United States District Court for the District of Columbia if such office is located in such District)."],[0,"(c) Furnishing information and assistance; directing vocational rehabilitation"],[0,"(1) The Secretary shall, upon request, provide persons covered by this chapter with information and assistance relating to the chapter's coverage and compensation and the procedures for obtaining such compensation and including assistance in processing a claim. The Secretary may, upon request, provide persons covered by this chapter with legal assistance in processing a claim. The Secretary shall also provide employees receiving compensation information on medical, manpower, and vocational rehabilitation services and assist such employees in obtaining the best such services available."],[0,"(2) The Secretary shall direct the vocational rehabilitation of permanently disabled employees and shall arrange with the appropriate public or private agencies in States or Territories, possessions, or the District of Columbia for such rehabilitation. The Secretary may in his discretion furnish such prosthetic appliances or other apparatus made necessary by an injury upon which an award has been made under this chapter to render a disabled employee fit to engage in a remunerative occupation. Where necessary rehabilitation services are not available otherwise, the Secretary of Labor may, in his discretion, use the fund provided for in section 944 of this title in such amounts as may be necessary to procure such services, including necessary prosthetic appliance or other apparatus. This fund shall also be available in such amounts as may be authorized in annual appropriations for the Department of Labor for the costs of administering this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/939?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§939. Administration by Secretary","tname":"Navigation and Navigable Waters","by":{"0":"13, 3, 5"}},{"t":"usc","label":"33 U.S.C. § 941","url":"https://www.law.cornell.edu/uscode/text/33/941","by":{"0":"6"}},{"t":"usc","label":"33 U.S.C. § 944","url":"https://www.law.cornell.edu/uscode/text/33/944","stext":{"head":"§944. Special fund","paras":[[0,"(a) Establishment; administration; custody, trust"],[0,"There is established in the Treasury of the United States a special fund. Such fund shall be administered by the Secretary. The Treasurer of the United States shall be the custodian of such fund, and all moneys and securities in such fund shall be held in trust by such Treasurer and shall not be money or property of the United States."],[0,"(b) Disbursements; bond of custodian"],[0,"The Treasurer is authorized to disburse moneys from such fund only upon order of the Secretary. He shall be required to give bond in an amount to be fixed and with securities to be approved by the Secretary of the Treasury and the Comptroller General of the United States conditioned upon the faithful performance of his duty as custodian of such fund."],[0,"(c) Payments into fund"],[0,"Payments into such fund shall be made as follows:"],[1,"(1) Whenever the Secretary determines that there is no person entitled under this chapter to compensation for the death of an employee which would otherwise be compensable under this chapter, the appropriate employer shall pay $5,000 as compensation for the death of such an employee."],[1,"(2) At the beginning of each calendar year the Secretary shall estimate the probable expenses of the fund during that calendar year and the amount of payments required (and the schedule therefor) to maintain adequate reserves in the fund. Each carrier and self-insurer shall make payments into the fund on a prorated assessment by the Secretary determined by—"],[2,"(A) computing the ratio (expressed as a percent) of (i) the carrier's or self-insured's workers' compensation payments under this chapter during the preceding calendar year, to (ii) the total of such payments by all carriers and self-insureds under this chapter during such year;"],[2,"(B) computing the ratio (expressed as a percent) of (i) the payments under section 908(f) of this title during the preceding calendar year which are attributable to the carrier or self-insured, to (ii) the total of such payments during such year attributable to all carriers and self-insureds;"],[2,"(C) dividing the sum of the percentages computed under subparagraphs (A) and (B) for the carrier or self-insured by two; and"],[2,"(D) multiplying the percent computed under subparagraph (C) by such probable expenses of the fund (as determined under the first sentence of this paragraph)."],[1,"(3) All amounts collected as fines and penalties under the provisions of this chapter shall be paid into such fund."],[0,"(d) Investigations; records, availability; recordkeeping; provisions of sections 49 and 50 of title 15 applicable to Secretary"],[0,"(1) For the purpose of making rules, regulations, and determinations under this section under and for providing enforcement thereof, the Secretary may investigate and gather appropriate data from each carrier and self-insurer. For that purpose, the Secretary may enter and inspect such places and records (and make such transcriptions thereof), question such employees, and investigate such facts, conditions, practices, or matters as he may deem necessary or appropriate."],[0,"(2) Each carrier and self-insurer shall make, keep, and preserve such records, and make such reports and provide such additional information, as prescribed by regulation or order of the Secretary, as the Secretary deems necessary or appropriate to carry out his responsibilities under this section."],[0,"(3) For the purpose of any hearing or investigation related to determinations or the enforcement of the provisions of this section, the provisions of sections 49 and 50 of title 15 (relating to the attendance of witnesses and the production of books, papers, and documents) are hereby made applicable to the jurisdiction, powers, and duties of the Secretary of Labor."],[0,"(e) Depositories; investments"],[0,"The Treasurer of the United States shall deposit any moneys paid into such fund into such depository banks as the Secretary may designate and may invest any portion of the funds which, in the opinion of the Secretary, is not needed for current requirements, in bonds or notes of the United States or of any Federal land bank."],[0,"(f) Limitation of liability"],[0,"Neither the United States nor the Secretary shall be liable in respect of payments authorized under section 908 of this title in an amount greater than the money or property deposited in or belonging to such fund."],[0,"(g) Audit by Comptroller General; finality of payment determinations; credits of disbursing officers"],[0,"The Comptroller General of the United States shall audit the account for such fund, but the action of the Secretary in making payments from such fund shall be final and not subject to review, and the Comptroller General is authorized and directed to allow credit in the accounts of any disbursing officer of the Secretary for payments made from such fund authorized by the Secretary."],[0,"(h) Civil actions for civil penalties and unpaid assessments"],[0,"All civil penalties and unpaid assessments provided for in this chapter shall be collected by civil suit brought by the Secretary."],[0,"(i) Proceeds available for certain payments"],[0,"The proceeds of this fund shall be available for payments:"],[1,"(1) Pursuant to sections 1 910 of this title with respect to certain initial and subsequent annual adjustments in compensation for total permanent disability or death."],[1,"(2) Under section 908(f) and (g), under section 918(b), and under section 939(c) of this title."],[1,"(3) To repay the sums deposited in the fund pursuant to subsection (d)."],[1,"(4) To defray the expense of making examinations as provided in section 907(e) of this title."],[0,"(j) Audit to Congress"],[0,"The fund shall be audited annually and the results of such audit shall be included in the annual report required by section 942 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/944?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§944. Special fund","tname":"Navigation and Navigable Waters","by":{"0":"6"}},{"t":"usc","label":"29 U.S.C. § 661","url":"https://www.law.cornell.edu/uscode/text/29/661","by":{"0":"10"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"16"}},{"t":"reg","label":"Sec. Order 38-72, 38 Fed. Reg. 90","url":"https://www.govinfo.gov/link/fr/38/90","by":{"0":"10"}}]};